  "channel": "#soc-incidents",
  "messages": [
    {
      "author": "Imre Haviland",
      "text": "Grant 8077 was disabled by the EDR quarantine on the 7th \u2014 not live. 8060 is owner-held for the substation laptop until the field rota ends; lifting that is Nienke's.",
      "ts": "2026-06-08T08:20:00"
    },
    {
      "author": "Beatriz Soriano",
      "text": "Responder 2's Friday PM is the change-freeze review, protected. No out-of-hours blocks pre-approved.",
      "ts": "2026-06-08T08:34:00"
    },
    {
      "author": "Maja Lindqvist",
      "text": "The change window is Wednesday the 17th. I need the review done and evidenced before it.",
      "ts": "2026-06-08T08:50:00"
    }
  ],
  "thread_id": "CHAT-1007",
  "title": "SEC-0007 engineering laptop certificates"
}

{
  "as_of": "2026-06-08",
  "bridges": [
    {
      "bridge_id": "BRG-70900",
      "end": "2026-06-25T11:00:00",
