  "revocations": [
    {
      "revocation_id": "RVK-3400",
      "status": "COMPLETED"
    }
  ]
}

{
  "case_reference": "SEC-0007",
  "messages": [
    {
      "author": "operations",
      "sent_at": "2026-06-08T08:35:00",
      "text": "Use immutable subject GRANT-DEVICE-CERT; the similarly named archived record is not in scope."
    },
    {
      "author": "governance",
      "sent_at": "2026-06-08T08:41:00",
      "text": "Current revision is v1. Confirm the signed approval before any state change."
    },
    {
      "author": "requester",
